/* Generated by `helix system machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type ChoiceContext, type ChoiceInput, acts, anchorArrival, anchorFrom, anchorOn, arrivalChanges, choosesNothing, clearable, enterActs, everyChanges, extending, letGo, movesAnchor, pressChanges, startsRange, takeArrival, takeEvery, takePress } from './machine.js'

export type { ChoiceContext, ChoiceInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'multipleSelection'

/** The state `choosing`. */
export const STATE_CHOOSING = 0
/** The state `none`. */
export const STATE_NONE = 1
/** Each state's name, by its number. */
export const STATES = ['choosing', 'none'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['choosing', 'none'] as const

/** The event `PRESS`. */
export const EVENT_PRESS = 0
/** The event `SPACE`. */
export const EVENT_SPACE = 1
/** The event `ARRIVE`. */
export const EVENT_ARRIVE = 2
/** The event `ALL`. */
export const EVENT_ALL = 3
/** The event `CLEAR`. */
export const EVENT_CLEAR = 4
/** The event `ENTER`. */
export const EVENT_ENTER = 5
/** Each event's name, by its number. */
export const EVENTS = ['PRESS', 'SPACE', 'ARRIVE', 'ALL', 'CLEAR', 'ENTER'] as const

/** The effect `act`. */
export const EFFECT_ACT = 0
/** The effect `announce`. */
export const EFFECT_ANNOUNCE = 1
/** Each effect's name, by its number. */
export const EFFECTS = ['act', 'announce'] as const

/** The request event `change`. */
export const ASK_CHANGE = 0
/** Each request event's name, by its number. */
export const ASKS = ['change'] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: ChoiceContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (context: ChoiceContext): number =>
  choosesNothing(context) ? STATE_NONE : STATE_CHOOSING

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (_state: number): readonly Effect[] => []

/** What `choosing` does with each event. */
const inChoosing = (context: ChoiceContext, event: number, input: ChoiceInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_PRESS:
      return acts(context, input) ? { context: context, effects: [[EFFECT_ACT]], state: STATE_CHOOSING } : pressChanges(context, input) ? { accept: { context: takePress(context, input), effects: [[EFFECT_ANNOUNCE]], state: STATE_CHOOSING }, ask: [ASK_CHANGE], refuse: { context: anchorOn(context, input), effects: [], state: STATE_CHOOSING } } : movesAnchor(context, input) ? { context: anchorOn(context, input), effects: [], state: STATE_CHOOSING } : undefined
    case EVENT_SPACE:
      return pressChanges(context, input) ? { accept: { context: takePress(context, input), effects: [[EFFECT_ANNOUNCE]], state: STATE_CHOOSING }, ask: [ASK_CHANGE], refuse: { context: anchorOn(context, input), effects: [], state: STATE_CHOOSING } } : movesAnchor(context, input) ? { context: anchorOn(context, input), effects: [], state: STATE_CHOOSING } : undefined
    case EVENT_ARRIVE:
      return arrivalChanges(context, input) ? { accept: { context: takeArrival(context, input), effects: [[EFFECT_ANNOUNCE]], state: STATE_CHOOSING }, ask: [ASK_CHANGE], refuse: { context: anchorArrival(context, input), effects: [], state: STATE_CHOOSING } } : extending(context, input) ? { context: anchorArrival(context, input), effects: [], state: STATE_CHOOSING } : startsRange(context, input) ? { context: anchorFrom(context, input), effects: [], state: STATE_CHOOSING } : undefined
    case EVENT_ALL:
      return everyChanges(context, input) ? { accept: { context: takeEvery(context, input), effects: [[EFFECT_ANNOUNCE]], state: STATE_CHOOSING }, ask: [ASK_CHANGE], refuse: { context: context, effects: [], state: STATE_CHOOSING } } : undefined
    case EVENT_CLEAR:
      return clearable(context, input) ? { accept: { context: letGo(context), effects: [[EFFECT_ANNOUNCE]], state: STATE_CHOOSING }, ask: [ASK_CHANGE], refuse: { context: context, effects: [], state: STATE_CHOOSING } } : undefined
    case EVENT_ENTER:
      return enterActs(context, input) ? { context: context, effects: [[EFFECT_ACT]], state: STATE_CHOOSING } : undefined
  }
  return undefined
}

/** What `none` does with each event. */
const inNone = (context: ChoiceContext, event: number, input: ChoiceInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_PRESS:
      return acts(context, input) ? { context: context, effects: [[EFFECT_ACT]], state: STATE_NONE } : undefined
    case EVENT_ENTER:
      return enterActs(context, input) ? { context: context, effects: [[EFFECT_ACT]], state: STATE_NONE } : undefined
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: ChoiceContext, event: number, input: ChoiceInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_CHOOSING:
      return inChoosing(context, event, input)
    case STATE_NONE:
      return inNone(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (_state: number, _context: ChoiceContext, _owner: number): Move | undefined =>
  undefined

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: ChoiceContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
